contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Read the pre-call observable balance of c.
        uint beforeBalance = address(c).balance;

        // Fund c so the rule has a non-trivial balance to observe.
        c.multiplicate{value: amount}(address(c));

        // After funding, capture the balance that withdraw is expected to move.
        uint fundedBalance = address(c).balance;

        // The test contract is the Owner (deployer of c). Call withdraw.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: an Owner call must not revert, and must drain c completely.
        assert(!reverted && address(c).balance == 0 && fundedBalance >= beforeBalance);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, address recipient) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        require(recipient != address(0), "invalid recipient");

        // Read the pre-call observable balance of c.
        uint beforeC = address(c).balance;
        uint beforeRecipient = address(recipient).balance;

        // Call multiplicate with the given amount.
        try c.multiplicate{value: amount}(recipient) {
            // On success, the rule is: the recipient should have received
            // exactly beforeC + amount (provided amount >= beforeC).
            assert(
                amount >= beforeC &&
                address(recipient).balance == beforeRecipient + beforeC + amount &&
                address(c).balance == 0
            );
        } catch {
            // On failure (revert), the rule is: amount < beforeC and balances are unchanged.
            assert(
                amount < beforeC &&
                address(c).balance == beforeC &&
                address(recipient).balance == beforeRecipient
            );
        }
    }
}

