contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0);

        uint balBefore = address(c).balance;

        // If c's balance does not cover the incoming value, the transfer in
        // multiplicate must revert because address(this).balance+msg.value >= address(this).balance
        // is checked but the actual transfer of that amount requires balance+value <= balance,
        // i.e. value == 0.
        bool reverted;
        if (amount > balBefore) {
            try c.multiplicate{value: amount}(address(0xdead)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // No call, so reverted remains default false; but this branch is not the rule's concern.
            reverted = true;
        }

        // General rule: when the incoming value exceeds c's current balance,
        // the call must revert so c's balance cannot decrease via multiplicate.
        assert(amount > balBefore ? (reverted && address(c).balance == balBefore) : true);
    }

    receive() external payable {}
}

